sysauto_script.script:
/* PTAG Hub I8: recompute age_days = whole days since state_entered_on for
   open (non-terminal) requests. Pure stamp: no workflow, no audit churn. */
var TERMINAL = '3,7,8,9';
var now = new GlideDateTime();
var n = 0;
var gr = new GlideRecord('x_snc_ptag_engage_engagement_request');
gr.addQuery('state', 'NOT IN', TERMINAL);
gr.addNotNullQuery('state_entered_on');
gr.query();
while (gr.next()) {
    var entered = new GlideDateTime(gr.getValue('state_entered_on'));
    var days = Math.floor((now.getNumericValue() - entered.getNumericValue()) / 86400000);
    if (days < 0) days = 0;
    if (parseInt(gr.getValue('age_days'), 10) !== days) {
        gr.setValue('age_days', days);
        gr.setWorkflow(false);
        gr.autoSysFields(false);
        gr.update();
        n++;
    }
}
gs.info('[PTAG aging] age_days stamped on ' + n + ' record(s)');
